    /** Pause (true) or resume (false) the plan on the sheet's today: refused for pausing a paused plan or
     *  resuming a running one. */
    @Transactional
    public Plan pause(String sheetId, String user, long planId, boolean on) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        Plan plan = plans.findForUpdate(planId).filter((p) -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan."));
        if (on && plan.isPaused()) throw refused("The plan is paused already.");
        if (!on && !plan.isPaused()) throw refused("The plan is not paused.");
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        LocalDate today = sheets.today(sheetId);
        if (on) plan.pause(today);
        else plan.resume(today);
        plans.saveAndFlush(plan);
        audit.recordOnCommit((on ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " start=" + plan.getStart());
        return plan;
    }

    /** Change the plan's amount on the sheet's today, for the claims generated from then on: refused for an
     *  amount not above 0.00 or with more than two decimals. */
    @Transactional
    public Plan changeAmount(String sheetId, String user, long planId, BigDecimal amount) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        Plan plan = plans.findForUpdate(planId).filter((p) -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan."));
        if (amount.signum() <= 0) throw refused("The amount must be more than 0.00.");
        if (amount.stripTrailingZeros().scale() > 2) throw refused("The amount has at most two decimals.");
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        plan.changeAmount(sheets.today(sheetId), amount.setScale(2));
        plans.saveAndFlush(plan);
        audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " start=" + plan.getStart() + " amount=" + plan.getAmount().toPlainString());
        return plan;
    }

    /** For every plan on the sheet, in the order they were added, make a DRAFT claim of its amount, dated
     *  the plan date with an empty note, for each plan date up to its end and the sheet's today that has
     *  none yet and no pause skips. Each claim is added by the claim form's rules, on its own: a date the form refuses is
     *  skipped and tried again next time. A plan naming a descendant sheet makes its claims on that sheet, by
     *  its rules and in its audit, for the person of the same name there; none while there is no such person.
     *  The claims made, oldest first; a viewer makes none. */
    public List<Claim> generate(String sheetId, String user) {
        sheets.load(sheetId);
        if (settings.roleOf(sheetId, user) == Role.VIEWER) return List.of();
        LocalDate today = sheets.today(sheetId);
        List<Claim> made = new ArrayList<>();
        for (Plan plan : plans.findBySheetIdOrderByIdAsc(sheetId)) {
            for (LocalDate date : plan.datesUpTo(today)) {
                if (plan.hasGenerated(date)) continue;
                try {
                    Claim claim = transaction.execute((status) -> generateOn(sheetId, user, plan.getId(), date));
                    if (claim != null) made.add(claim);
                } catch (ResponseStatusException refused) {
                    // The claim form refuses the date: it is tried again by the next generate.
                }
            }
        }
        return made;
    }

    /** Make the plan's claim for the date, unless it has one already. */
    private Claim generateOn(String sheetId, String user, long planId, LocalDate date) {
        Plan plan = plans.findForUpdate(planId).orElse(null);
        if (plan == null || plan.hasGenerated(date)) return null;
        String target = plan.getTargetSheetId();
        Long personId = plan.getPersonId();
        if (target != null) {
            Person person = people.findByIdAndSheetId(personId, sheetId).orElse(null);
            if (person == null) return null;
            Person there = people.findBySheetIdAndNameKey(target, Person.keyOf(person.getName())).orElse(null);
            if (there == null) return null;
            personId = there.getId();
        }
        Claim claim = claims.add(target != null ? target : sheetId, user, personId, plan.getAmount(), date, "",
                null, null, null);
        plan.markGenerated(date);
        plans.saveAndFlush(plan);
        return claim;
    }

    /** The sheet's descendants: the sheets naming it as their parent, then theirs, and so on. */
    private Set<String> descendantsOf(String sheetId) {
        Set<String> found = new HashSet<>();
        Deque<String> next = new ArrayDeque<>(List.of(sheetId));
        while (!next.isEmpty()) {
            for (SheetParentLink child : parents.findByParentId(next.pop())) {
                if (!child.getSheetId().equals(sheetId) && found.add(child.getSheetId())) next.add(child.getSheetId());
            }
        }
        return found;
    }

    private static ResponseStatusException refused(String why) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, why);
    }
}
package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/plans")
@Validated
public class PlanController {

    /** What the screen shows of a plan; the amount always has two decimals. Generated is how many claims
     *  it has made so far; next dates are its first five plan dates after the sheet's today, on or before
     *  its end and not skipped by a pause, oldest first. Paused is whether it is paused now. Changes are the lines
     *  of its amount changes, oldest first: the day, then amount=the new amount. */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every,
            Integer day, LocalDate end, int generated, List<LocalDate> nextDates, boolean paused,
            List<String> changes, String sheet) {
        static PlanView of(Plan plan, LocalDate today) {
            return new PlanView(plan.getId(), plan.getPersonId(), plan.getAmount().toPlainString(), plan.getStart(),
                    plan.getEvery(), plan.getDay(), plan.getEnd(), plan.getGeneratedCount(),
                    plan.datesAfter(today, 5), plan.isPaused(), plan.changeLines(), plan.getTargetSheetId());
        }
    }

    /** A plan's fields as entered on the person's row; no start means the sheet's today. A plan has either
     *  every (days) or day (of the month, for a monthly plan). Sheet names a descendant sheet to make its
     *  claims on; none means this sheet. */
    public record PlanForm(@NotNull Long personId, @NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate start, Integer every, Integer day, @NotNull LocalDate end, @Size(max = 100) String sheet) {
    }

    /** A plan's new amount as entered. */
    public record AmountForm(@NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount) {
    }

    /** How many claims a generate made, the claims, oldest first, and the sheet's plans as they are then. */
    public record GenerateView(int generated, List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;

    public PlanController(PlanService service) {
        this.service = service;
    }

    /** The sheet's plans in the order they were added. */
    @GetMapping
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String id = sheetId.trim();
        LocalDate today = service.today(id);
        return service.list(id).stream().map((plan) -> PlanView.of(plan, today)).toList();
    }

    /** Add a plan to a person. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PlanForm form) {
        String id = sheetId.trim();
        return PlanView.of(service.add(id, SignedInUser.name(user), form.personId(), form.amount(),
                form.start(), form.every(), form.day(), form.end(), form.sheet()), service.today(id));
    }

    /** Pause the plan from the sheet's today. */
    @PostMapping("/{planId}/pause")
    public PlanView pause(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String id = sheetId.trim();
        return PlanView.of(service.pause(id, SignedInUser.name(user), planId, true), service.today(id));
    }

    /** Resume the plan from the sheet's today. */
    @PostMapping("/{planId}/resume")
    public PlanView resume(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String id = sheetId.trim();
        return PlanView.of(service.pause(id, SignedInUser.name(user), planId, false), service.today(id));
    }

    /** Change the plan's amount from the sheet's today. */
    @PostMapping("/{planId}/amount")
    public PlanView changeAmount(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid AmountForm form) {
        String id = sheetId.trim();
        return PlanView.of(service.changeAmount(id, SignedInUser.name(user), planId, form.amount()),
                service.today(id));
    }

    /** Make the plans' claims due by the sheet's today. */
    @PostMapping("/generate")
    public GenerateView generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String id = sheetId.trim();
        List<ClaimView> claims = service.generate(id, SignedInUser.name(user)).stream().map(ClaimView::of).toList();
        LocalDate today = service.today(id);
        return new GenerateView(claims.size(), claims,
                service.list(id).stream().map((plan) -> PlanView.of(plan, today)).toList());
    }
}
