package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person's plan: a claim of its amount on every plan date, up to its end. The plan dates are either the
 *  start then every N days, or, for a monthly plan, its day of the month in every month from the start's
 *  month (a day beyond the month's length falling on its last day), those before the start left out. */
@Entity
@Table(name = "person_plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** Every N days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan; null for any other. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    /** The descendant sheet its claims are made on, for the person of the same name there; null for its own
     *  sheet and person. */
    @Column(name = "target_sheet_id")
    private String targetSheetId;

    /** The plan dates it has made a claim for. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_plan_date", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "plan_date", nullable = false)
    private Set<LocalDate> generated = new HashSet<>();

    /** Its pauses, oldest first; one is still open while the plan is paused. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderBy("pausedOn")
    private List<PlanPause> pauses = new ArrayList<>();

    /** The changes of its amount, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "position")
    private List<PlanChange> changes = new ArrayList<>();

    protected Plan() {
    }

    Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end, String targetSheetId) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
        this.targetSheetId = targetSheetId;
    }

    /** The plan dates, oldest first, on or before both its end and the date, those a pause skips left out. */
    List<LocalDate> datesUpTo(LocalDate upTo) {
        return scheduleUpTo(upTo).stream().filter((d) -> pauses.stream().noneMatch((p) -> p.skips(d))).toList();
    }

    /** The plan dates by its schedule alone, oldest first, on or before both its end and the date. */
    private List<LocalDate> scheduleUpTo(LocalDate upTo) {
        LocalDate last = end.isBefore(upTo) ? end : upTo;
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) dates.add(d);
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate d = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!d.isBefore(start) && !d.isAfter(last)) dates.add(d);
        }
        return dates;
    }

    /** Up to the first count plan dates by its schedule, oldest first, after the date and on or before its
     *  end; a pause does not hide them (it only skips them when claims are generated). */
    public List<LocalDate> datesAfter(LocalDate after, int count) {
        return scheduleUpTo(end).stream().filter((d) -> d.isAfter(after)).limit(count).toList();
    }

    boolean hasGenerated(LocalDate date) {
        return generated.contains(date);
    }

    void markGenerated(LocalDate date) {
        generated.add(date);
    }

    /** Whether the plan is paused now. */
    public boolean isPaused() {
        return pauses.stream().anyMatch(PlanPause::isOpen);
    }

    /** Pause the plan on the date; the caller has checked it is running. */
    void pause(LocalDate on) {
        pauses.add(new PlanPause(on));
    }

    /** Resume the plan on the date; the caller has checked it is paused. */
    void resume(LocalDate on) {
        pauses.stream().filter(PlanPause::isOpen).forEach((p) -> p.resume(on));
    }

    /** Change the amount on the date, for the claims generated from then on. */
    void changeAmount(LocalDate on, BigDecimal newAmount) {
        amount = newAmount;
        changes.add(new PlanChange(on, newAmount));
    }

    /** The lines of its amount changes, oldest first: the day, then amount=the new amount. */
    public List<String> changeLines() {
        return changes.stream().map(PlanChange::line).toList();
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    public String getTargetSheetId() {
        return targetSheetId;
    }

    /** How many claims the plan has made so far. */
    public int getGeneratedCount() {
        return generated.size();
    }
}

    /** Once a holiday is added to the sheet, the due-by of every claim neither SETTLED nor VOID whose
     *  due-by is on or after the holiday is worked out again: the terms-th business day after the claim's
     *  date, with the terms the claim was fixed with, past the holidays now. */
    @EventListener
    @Transactional
    public void moveDueBys(HolidaysChanged change) {
        String sheetId = change.sheetId();
        Set<LocalDate> days = holidays.dates(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) continue;
            if (claim.getDueBy().isBefore(change.date())) continue;
            if (claim.moveDueBy(BusinessDays.after(claim.getDate(), claim.getTerms(), days))) {
                claims.save(claim);
            }
        }
        claims.flush();
        rollup.recordChanges(change.user(), before);
    }

    /** Once the sheet's today is changed, every lock on its claims is released. */
    @EventListener
    @Transactional
    public void releaseLocks(TodayChanged change) {
        claims.releaseLocks(change.sheetId());
    }

    private static void refuseUnlessDraft(Claim claim) {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
        }
    }

    /** Refuse a change to a claim whose editor another user has open. */
    private static void refuseIfLocked(Claim claim, String user) {
        if (claim.isLockedAgainst(user)) {
            throw new ResponseStatusException(HttpStatus.LOCKED,
                    "The claim is being edited by " + claim.getLockedBy() + ".");
        }
    }

    /** Change a draft claim's amount, date and note; a blank date takes the sheet's today. A claim that
     *  is no longer a draft is refused: to change an open claim, void it and add a new one. A claim
     *  another user's editor locks is refused; saving releases the user's own lock. A save whose date's
     *  due-by, as a claim of its person added on it would be fixed now, falls inside a closed period is
     *  refused, the date unchanged or not; the claim's own due-by stays as it was fixed. */
    @Transactional
    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        LocalDate dated = dateOr(sheetId, date);
        refuseIfClosed(sheetId, claim.getDueBy());
        refuseUnlessDraft(claim);
        refuseIfLocked(claim, user);
        Person person = person(sheetId, claim.getPersonId());
        refuseIfRetired(person, dated);
        refuseIfClosed(sheetId, holidays.dueBy(sheetId, dated, termsOf(sheetId, person, dated)));
        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A claim with lines has the total of its lines as its amount.");
        }
        refuseIfNotCorrecting(sheetId, claim.getPersonId(), amount, corrects, claim.getId());
        String reference = refOf(ref);
        refuseIfRefUsed(sheetId, reference, claim.getId());
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        claim.set(amount, dated, noteOf(note), corrects);
        claim.setRef(reference);
        List<String> tagged = tagsOf(tags);
        claim.setTags(tagged);
        useTags(sheetId, tagged);
        claim.lockFor(null);
        claim.setEditedBy(user);
        Claim saved = claims.saveAndFlush(claim);
        recordChange("CLAIM_EDITED", user, person(sheetId, saved.getPersonId()), saved);
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
     *  by the user who opened or last edited the claim, and an action the sheet's permission matrix does
     *  not allow the user's role. A clerk's settling of a claim whose due is above the clerk
     *  limit in force (its person's grade's own, else the sheet's) leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
     *  steward settles anything). */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
        return changeStatus(sheetId, user, id, next, null);
    }

    /** Make the claims a bulk settle settled (or left pending) the sheet's next settle batch: each shows
     *  its number. Its audit line, after the claims' own, carries the batch's number, how many claims it
     *  has and the frozen dues of those SETTLED added up. Returns the batch's number. */
    @Transactional
    public int markSettleBatch(String sheetId, String user, List<Claim> settled) {
        int batch = sheets.nextSettleBatch(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : settled) {
            Claim row = claims.findForUpdate(claim.getId(), sheetId).orElseThrow();
            row.setSettleBatch(batch);
            claims.save(row);
            claim.setSettleBatch(batch);
            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
                total = total.add(claim.getSettledDue());
            }
        }
        claims.flush();
        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
                + " count=" + settled.size() + " total=" + total.toPlainString());
        return batch;
-- A person's plans: an amount, a start date, every N days (at least 1) and an end date. Generating
-- makes a DRAFT claim for each plan date (the start, then every N days) up to the end and the
-- sheet's today; person_plan_date keeps each date a plan has made its claim for, so it is made once.
CREATE TABLE person_plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    amount     DECIMAL(12, 2) NOT NULL,
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL,
    end_date   DATE           NOT NULL
);
CREATE INDEX person_plan_sheet ON person_plan (sheet_id);
CREATE TABLE person_plan_date (
    plan_id   BIGINT NOT NULL REFERENCES person_plan (id) ON DELETE CASCADE,
    plan_date DATE   NOT NULL,
    PRIMARY KEY (plan_id, plan_date)
);
-- A plan may be paused and resumed, each on the sheet's today then. A plan date on or after the day it
-- was paused and before the day it was resumed is skipped, not postponed: generating never makes its
-- claim. Each pause is one row; resumed_on is null while the plan is still paused.
CREATE TABLE person_plan_pause (
    plan_id    BIGINT NOT NULL REFERENCES person_plan (id) ON DELETE CASCADE,
    paused_on  DATE   NOT NULL,
    resumed_on DATE
);
CREATE INDEX person_plan_pause_plan ON person_plan_pause (plan_id);
-- A plan's amount may be changed, on the sheet's today then. The new amount applies to the claims
-- generated from then on; claims already generated keep theirs. Each change is one row, kept in the
-- order they were made (position), with the day it was made and the new amount.
CREATE TABLE person_plan_change (
    plan_id    BIGINT         NOT NULL REFERENCES person_plan (id) ON DELETE CASCADE,
    position   INT            NOT NULL,
    changed_on DATE           NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (plan_id, position)
);
-- A restricted user is a fourth role: it is listed only the people of the crews its person leads or
-- belongs to, and that person. The role check is widened by rebuilding the table, as its check
-- constraint has no name to drop.
CREATE TABLE sheet_role_r (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer', 'restricted')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_r (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_r RENAME TO sheet_role;
-- A plan may name one of its sheet's descendants: its claims are then made for the person of the same
-- name on that sheet (none when there is no such person), by that sheet's rules and in its audit.
ALTER TABLE person_plan ADD COLUMN target_sheet_id VARCHAR(100);
-- Closing or soft-closing a period also fixes, at that moment, every pool member's cut for it: the cut
-- each member of each pool (a crew's under its id negated) showed then, by member key (the person's id,
-- or pool-<name> for a member pool). A pool with no row showed no cuts then. Reopening removes the rows:
-- the cuts for the period are live again.
CREATE TABLE period_pool_cut (
    period_id  BIGINT         NOT NULL REFERENCES period (id),
    pool_id    BIGINT         NOT NULL,
    member_key VARCHAR(300)   NOT NULL,
    cut        DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, pool_id, member_key)
);
