import { HttpClient } from '@angular/common/http';
import { Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { ClaimView } from '../claims/claims-api';

/** A person's plan: a claim of the amount (two decimals) on the start date and every `every` days after
 *  it, or, for a monthly plan, on its `day` of every month from the start's month (a day beyond the
 *  month's length falling on its last day, those before the start left out), up to the end date
 *  (yyyy-mm-dd). Generated is how many claims it has made so far; next dates are its first five plan
 *  dates after the sheet's today and on or before the end, those a pause skips left out, oldest first.
 *  Paused is whether it is paused now: a plan date on or after the day it was paused and before the day
 *  it was resumed is skipped, not postponed. */
export interface PlanView {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
  nextDates: string[];
  paused: boolean;
  /** Its amount changes, oldest first, each as `<date> amount=<amount>`. */
  changes: string[];
  /** The descendant sheet its claims are made on, for the person of the same name there; null for this one. */
  sheet: string | null;
}

/** A plan's fields as entered; a null start is the sheet's today. A plan has either every or day. A
 *  sheet names one of the sheet's descendants to make its claims on; null is the sheet itself. */
export interface PlanFields {
  amount: string;
  start: string | null;
  every: string | null;
  day: string | null;
  end: string;
  sheet: string | null;
}

/** What a generate made: how many claims, the claims oldest first, and the sheet's plans then. */
export interface GenerateView {
  generated: number;
  claims: ClaimView[];
  plans: PlanView[];
}

// The plans of a sheet, as the store holds them.
@Injectable({ providedIn: 'root' })
export class PlansApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/plans`;
  }

  /** The sheet's plans in the order they were added. */
  list(sheetId: string): Promise<PlanView[]> {
    return firstValueFrom(this.http.get<PlanView[]>(this.url(sheetId)));
  }

  /** Add a plan to a person: refused for an amount not above 0.00 with up to two decimals, neither or
   *  both of an interval and a day of the month, an interval that is not a whole number of at least 1, a
   *  day of the month outside 1 to 31, an end before the start, or a sheet that is not a descendant. */
  add(sheetId: string, personId: number, f: PlanFields): Promise<PlanView> {
    return firstValueFrom(this.http.post<PlanView>(this.url(sheetId),
      { personId, amount: f.amount, start: f.start, every: f.every, day: f.day, end: f.end, sheet: f.sheet }));
  }

  /** Pause (true) or resume (false) a plan on the sheet's today: refused for pausing a paused plan or
   *  resuming a running one. */
  pause(sheetId: string, planId: number, on: boolean): Promise<PlanView> {
    return firstValueFrom(this.http.post<PlanView>(`${this.url(sheetId)}/${planId}/${on ? 'pause' : 'resume'}`, {}));
  }

  /** Change a plan's amount on the sheet's today: refused for an amount not above 0.00 with up to two
   *  decimals. */
  changeAmount(sheetId: string, planId: number, amount: string): Promise<PlanView> {
    return firstValueFrom(this.http.post<PlanView>(`${this.url(sheetId)}/${planId}/amount`, { amount }));
  }

  /** Make every plan's claims due by the sheet's today. */
  generate(sheetId: string): Promise<GenerateView> {
    return firstValueFrom(this.http.post<GenerateView>(`${this.url(sheetId)}/generate`, {}));
  }
}

// The active sheet's plans. Each load of a sheet re-reads them from the store.
@Injectable({ providedIn: 'root' })
export class Plans {
  private readonly session = inject(Session);
  private readonly api = inject(PlansApi);

import { Component, computed, effect, inject, input, signal } from '@angular/core';
import { FigurePipe } from '../../core/figure.pipe';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { Plans } from './plans-api';

const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;
const EVERY = /^\d{1,6}$/;
const DAY = /^\d{1,2}$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// A person's plans, each with how many claims it has made so far and its next dates, and a form to add one.
@Component({
  selector: 'app-person-plans',
  imports: [FigurePipe, ReactiveFormsModule],
  template: `
    <ul [attr.aria-label]="'Plans of ' + personName()">
      @for (pl of plans(); track pl.id) {
        <li [attr.data-testid]="'plan-row-' + pl.id">
          <span data-testid="plan-amount-shown">{{ pl.amount | figure }}</span>
          @if (pl.day !== null) { monthly on day {{ pl.day }} } @else { every {{ pl.every }} days }
          from {{ pl.start }} to {{ pl.end }}@if (pl.sheet) { on sheet {{ pl.sheet }}}; made <span data-testid="plan-generated">{{ pl.generated }}</span>;
          next <span data-testid="plan-next-dates">{{ pl.nextDates.join(', ') }}</span>;
          paused <span data-testid="plan-paused">{{ pl.paused ? 'yes' : 'no' }}</span>
          <button type="button" data-testid="plan-pause" (click)="pause(pl.id, true)" [disabled]="pausing() === pl.id">
            Pause</button>
          <button type="button" data-testid="plan-resume" (click)="pause(pl.id, false)" [disabled]="pausing() === pl.id">
            Resume</button>
          <label [for]="'plan-amount-' + pl.id">New amount</label>
          <input [id]="'plan-amount-' + pl.id" data-testid="plan-amount" inputmode="decimal"
            [value]="amounts()[pl.id] ?? ''" (input)="amountInput(pl.id, $event)" />
          <button type="button" data-testid="plan-amount-save" (click)="changeAmount(pl.id)"
            [disabled]="pausing() === pl.id">Save amount</button>
          <ul [attr.aria-label]="'Amount changes'">
            @for (line of pl.changes; track $index) {
              <li data-testid="plan-change-line">{{ line }}</li>
            }
          </ul>
          @if (rowError()?.planId === pl.id) {
            <p role="alert" data-testid="plan-error">{{ rowError()?.message }}</p>
          }
        </li>
      }
    </ul>
    <form [formGroup]="form" (ngSubmit)="submit()" [attr.aria-label]="'Add a plan for ' + personName()">
      <label [for]="'plan-form-amount-' + personId()">Amount</label>
      <input [id]="'plan-form-amount-' + personId()" data-testid="plan-form-amount" formControlName="amount" inputmode="decimal" />
      <label [for]="'plan-form-start-' + personId()">Start</label>
      <input [id]="'plan-form-start-' + personId()" type="date" data-testid="plan-form-start" formControlName="start" />
      <label [for]="'plan-form-every-' + personId()">Every (days)</label>
      <input [id]="'plan-form-every-' + personId()" data-testid="plan-form-every" formControlName="every" inputmode="numeric" />
      <label [for]="'plan-form-day-' + personId()">Or day of month</label>
      <input [id]="'plan-form-day-' + personId()" data-testid="plan-form-day" formControlName="day" inputmode="numeric" />
      <label [for]="'plan-form-sheet-' + personId()">On sheet (a descendant)</label>
      <input [id]="'plan-form-sheet-' + personId()" data-testid="plan-form-sheet" formControlName="sheet" />
      <label [for]="'plan-form-end-' + personId()">End</label>
      <input [id]="'plan-form-end-' + personId()" type="date" data-testid="plan-form-end" formControlName="end" />
      <button type="submit" data-testid="plan-form-submit" [disabled]="saving()">Add plan</button>
      @if (error()) {
        <p role="alert" data-testid="plan-error">{{ error() }}</p>
                      }
                    }
                  </select>
                  <button type="button" data-testid="person-patron-add" (click)="addPatron(p, patronSelect)"
                    [disabled]="addingPatron() === p.id" [attr.aria-label]="'Add a patron for ' + p.name">Add patron</button>
                  @if (patronError()?.id === p.id) {
                    <p role="alert" data-testid="person-patron-error">{{ patronError()?.message }}</p>
                  }
                </td>
                <td>
                  <app-person-plans [personId]="p.id" [personName]="p.name" />
                </td>
                <td>
                  <app-person-claims [personId]="p.id" [personName]="p.name" [claims]="claimsOf(p.id)"
                    [people]="people()" [rates]="rates()" [grades]="p.grades" [periods]="periods()"
                    [selected]="selectedClaims()" (selectedChange)="selectClaim($event.id, $event.on)"

